import { LEGAL, LEGAL_FULL_ADDRESS } from "@/lib/legal";
import { legalText as p, LEGAL_POLICY, NOTES_SCOPE, SAVED_QUESTION_RETENTION, SUPPORT_HOURS, SUPPORT_RESPONSE, type LegalText } from "@/lib/legal-policy";

export type PolicyKey = "terms" | "dpa" | "privacy" | "security" | "aiTransparency" | "dataRights" | "accountDeletion" | "cookies" | "support";
export type PolicySection = { id?: string; title: LegalText; paragraphs: LegalText[] };
export type PolicyDocument = { title: LegalText; intro: LegalText; review?: boolean; sections: PolicySection[] };
const section = (sl: string, en: string, paragraphs: LegalText[], id?: string): PolicySection => ({ title: p(sl, en), paragraphs, id });
const identity = p(
  `Ponudnik je ${LEGAL.entityName}, ${LEGAL_FULL_ADDRESS}. Kontakt: ${LEGAL.generalEmail}; ${LEGAL.supportPhone}. Davčna številka: ${LEGAL_POLICY.taxNumber}. Identifikacija za DDV ${LEGAL_POLICY.vatId} velja od 1. novembra 2026.`,
  `The provider is ${LEGAL.entityName}, ${LEGAL_FULL_ADDRESS}. Contact: ${LEGAL.generalEmail}; ${LEGAL.supportPhone}. Tax number: ${LEGAL_POLICY.taxNumber}. VAT identification ${LEGAL_POLICY.vatId} takes effect on 1 November 2026.`,
);
const review = p(
  "Pogodbena različica za pregled. Potrjena poslovna pravila so vključena, pravni pregled in določene tehnične preveritve pa še niso zaključeni. Z objavo spletne strani se že podpisane pogodbe ne spreminjajo za nazaj. Velja različica, ki je ustrezno vključena v vaš dogovor, skupaj s prisilno zakonodajo.",
  "Contract review version. Confirmed commercial rules are included, but legal review and certain technical checks are not complete. Publishing this page does not retrospectively amend signed agreements. The version properly incorporated into your agreement and mandatory law apply.",
);
export const CONTRACT_REVIEW_NOTICE = review;

export const LEGAL_DOCUMENTS: Record<PolicyKey, PolicyDocument> = {
  terms: {
    title: p("Pogoji uporabe Calendra", "Calendra Terms of Service"),
    intro: p("Poslovne naročnine, plačila, podpora, uporaba podatkov in ločena pravila za uporabnike Connect in naročanja.", "Business subscriptions, payments, support, data use and separate rules for Connect and booking users."), review: true,
    sections: [
      section("1. Ponudnik in dokumenti pogodbe", "1. Provider and agreement", [identity, p("Poslovni naročnik ob začetku podpiše pogodbo. Podpisana pogodba oziroma sprejeta ponudba določi paket, ceno, uporabnike, obračunsko obdobje, datum podaljšanja in rok odpovedi. Ti pogoji in DPA veljajo v obsegu, v katerem so vključeni v dogovor. DPA ima prednost pri obdelavi osebnih podatkov; prisilna zakonodaja vedno prevlada. Ločene pravne osebe v skupnem delovnem prostoru morajo imeti ustrezno pooblastilo in pogodbeno ureditev.", "The business customer signs an initial agreement. That agreement or accepted offer identifies the package, price, users, billing period, renewal date and notice deadline. These Terms and the DPA apply to the extent incorporated into that agreement. The DPA prevails for personal-data processing; mandatory law always prevails. Separate legal entities sharing a workspace need appropriate authority and contractual coverage.")]),
      section("2. Storitev in podatki", "2. Service and data", [p("Calendra zagotavlja naročanje, koledar, poslovne podatke o strankah, opomnike, obračunavanje ter omogočene module in integracije. Vključene funkcije določa izbrani paket; načrtovane funkcije niso samodejno pogodbena obveznost. Calendra ni izvajalec zdravstvene ali psihološke obravnave in ni kanal za nujno pomoč.", "Calendra provides scheduling, calendars, business client records, reminders, billing and enabled modules and integrations. Included functions depend on the package; roadmap items are not automatically contractual commitments. Calendra is not a healthcare or counselling provider and is not an emergency service."), NOTES_SCOPE]),
      section("3. Računi, preizkus in pooblastila", "3. Accounts, trial and authority", [p("Naročnik zagotovi pravilne podatke, pooblaščenega skrbnika in dostop samo tistim uporabnikom, ki ga potrebujejo. Dostop ob odhodu sodelavca pravočasno odstrani. Prijavnih podatkov ne deli. Kjer je na voljo, preizkus traja 14 dni; sam preizkus ni dovoljenje za bremenitev. Plačljivo naročniško razmerje in način plačila določata podpisana pogodba oziroma sprejeta plačljiva ponudba.", "The customer supplies accurate information, an authorised administrator and access limited to users who need it. Access must be removed when a colleague leaves; credentials must not be shared. Where offered, the trial lasts 14 days. A trial alone does not authorise a payment charge. The signed agreement or accepted paid order determines the subscription and payment method.")]),
      section("4. Cene in DDV od 1. novembra 2026", "4. Prices and VAT from 1 November 2026", [p("Od 1. novembra 2026 so objavljene B2B naročniške cene brez DDV; prišteje se DDV, kadar se uporablja. Mesečni paket Basic se s 17,90 EUR spremeni na 15,90 EUR brez DDV. Pri običajni domači transakciji z 22-odstotnim DDV je primer 3,50 EUR DDV in 19,40 EUR skupaj po zaokroževanju. Davčna obravnava je odvisna od konkretne transakcije, zato 22 % ne velja avtomatično za vsakega kupca.", "From 1 November 2026, published B2B subscription prices exclude VAT; applicable VAT is added. The Basic monthly price changes from EUR 17.90 to EUR 15.90 excluding VAT. For an ordinary domestic transaction at 22% VAT, the example is EUR 3.50 VAT and EUR 19.40 total after rounding. Tax treatment depends on the transaction, so 22% is not automatically applicable to every customer."), p("Letne cene, drugi paketi, dodatni uporabniki, SMS, moduli in morebitne provizije se navedejo v veljavnem ceniku oziroma sprejeti ponudbi. Iz nove mesečne cene ne izhaja samodejno nova letna cena. Sprememba javnega cenika ne prepiše že sprejetih cen ali predplačanega obdobja. Davčno obravnavo predplačil in prehodnih računov se določi po veljavnih pravilih.", "Annual prices, other plans, additional users, SMS, modules and any transaction fees are set out in the applicable price list or accepted offer. A new monthly amount does not by itself establish a new annual price. A public price change does not rewrite accepted prices or prepaid periods. Advance payments and transition invoices follow applicable tax rules.")], "ddv"),
      section("5. Plačilo, opomin in omejitev dostopa", "5. Payment, reminder and access restriction", [p("Če podpisani dogovor ne določa drugače, je rok plačila 14 koledarskih dni od izdaje računa. Če nesporni znesek ni plačan, sledi pisni opomin sedem koledarskih dni po zapadlosti. Dostop se lahko omeji najprej 30 koledarskih dni po prejemu računa, ne 30 dni po zapadlosti. Upoštevata se dejanski prejem računa in predhodno obvestilo; omejitev ni obvezna avtomatika.", "Unless the signed agreement states otherwise, payment is due 14 calendar days after invoice issue. If an undisputed amount remains unpaid, a written reminder follows seven calendar days after the due date. Access may be restricted no earlier than 30 calendar days after receipt of the invoice, not 30 days overdue. Actual receipt and prior notice must be taken into account; restriction is discretionary, not an automatic requirement."), p("Če sta izdaja in prejem isti dan: 14. dan zapadlost, 21. dan opomin, od 30. dne možna omejitev. Sporne postavke sporočite čim prej; nesporni zneski ostanejo plačljivi. Omejitev dostopa ni izbris podatkov in ne odpravi obveznosti glede varstva podatkov, zakonitega izvoza ali obravnave zahtev.", "Where issue and receipt occur on the same day: payment is due on day 14, the reminder follows on day 21, and restriction is possible from day 30. Report disputed charges promptly; undisputed amounts remain payable. Restriction is not data deletion and does not remove obligations concerning privacy, lawful exports or rights requests.")]),
      section("6. Samodejno podaljšanje in odpoved", "6. Automatic renewal and cancellation", [p("Mesečne in letne naročnine se samodejno podaljšajo za naslednje dogovorjeno mesečno oziroma 12-mesečno obdobje na podlagi začetne pogodbe. Za nespremenjeno podaljšanje ni potreben nov podpis. Pisna odpoved oziroma obvestilo o nepodaljšanju mora prispeti na info@calendra.si najmanj 30 koledarskih dni pred naslednjim podaljšanjem, razen če podpisani dogovor dopušča ugodnejši rok.", "Monthly and annual subscriptions automatically renew for the next agreed monthly or 12-month period under the initial agreement. An unchanged renewal does not require a fresh signature. Written cancellation or non-renewal notice must reach info@calendra.si at least 30 calendar days before the next renewal, unless the signed agreement allows more favourable notice."), p("Poznejše obvestilo se upošteva ob prvem naslednjem podaljšanju, za katero je izpolnjen 30-dnevni rok; obvestila ni treba poslati ponovno. To lahko pomeni dodatno mesečno ali letno obdobje. Potrdimo prejem in datum prenehanja. Pri običajni odpovedi zaradi premisleka vračila ali sorazmernega vračila naročnine ni. To ne omejuje obveznih pravnih sredstev, popravka nepravilnih bremenitev ali pravic zaradi bistvene kršitve ponudnika.", "Later notice takes effect at the first subsequent renewal for which the 30-day deadline is met; notice need not be resubmitted. This can mean an additional monthly or annual period. We confirm receipt and the end date. Ordinary change-of-mind cancellation does not entitle the customer to a refund or prorated subscription refund. Mandatory remedies, correction of incorrect charges and rights arising from the provider's material breach remain unaffected.")]),
      section("7. Podpora in razpoložljivost", "7. Support and availability", [SUPPORT_HOURS, SUPPORT_RESPONSE, p("Podpora: info@calendra.si. Navedite prizadeto funkcijo, čas dogodka in poslovni vpliv, brez gesel, ključev ali podatkov drugih strank. Varnostno kršitev prijavite takoj. Obveznosti glede kršitev osebnih podatkov ne mirujejo ponoči. Brez posebej podpisanega dogovora ta dokument ne določa odstotka zajamčene razpoložljivosti ali zajamčenega časa obnove.", "Support: info@calendra.si. Describe the affected function, event time and business impact without passwords, keys or other clients' records. Report a suspected security breach immediately. Personal-data breach duties do not pause overnight. Without a separately signed agreement, this document does not establish a guaranteed uptime percentage or recovery time.")]),
      section("8. Dopustna uporaba in integracije", "8. Acceptable use and integrations", [p("Prepovedani so nepooblaščen dostop, motenje delovanja, testiranje brez dovoljenja, neželena sporočila in nezakonita obdelava. Naročnik odgovarja za svoje strokovne storitve, vsebino, cene, davčne nastavitve in zakonita navodila. Integracije lahko zahtevajo lasten račun in pogoje ponudnika. Calendra ne izključuje svojih obveznosti za izbrane podobdelovalce zgolj zato, ker gre za zunanjo storitev.", "Unauthorised access, disruption, testing without permission, unsolicited messages and unlawful processing are prohibited. The customer is responsible for its professional services, content, prices, tax configuration and lawful instructions. Integrations may require separate accounts and provider terms. Calendra does not exclude its obligations for engaged subprocessors merely because a service is external.")]),
      section("9. AI in opombe", "9. AI and notes", [p("Besedilni pomočnik za podporo je v uporabi in shranjevanje uporabniških vprašanj je vključeno. Glasovni sistem ni v uporabi. AI je pomoč pri uporabi produkta, ne strokovna diagnoza ali svetovanje. Odgovore preverite; na voljo je človeška podpora. Shranjevanje opomb na S3 ne pomeni dovoljenja za njihovo uporabo v podporni AI ali za učenje na evidencah strank.", "Text-based product support is live and user-question saving is enabled. The voice system is not live. AI provides product help, not professional diagnosis or counselling. Check answers and use human support when appropriate. S3 note storage does not authorise use of those notes in support AI or training on client records."), SAVED_QUESTION_RETENTION]),
      section("10. Izvoz, prenehanje in odgovornost", "10. Export, termination and liability", [p("Za izvoz ali prenos podatkov kontaktirajte info@calendra.si. Ob prenehanju Calendra po izbiri upravljavca vrne ali izbriše osebne podatke in kopije, razen če pravo zahteva hrambo. Izvedbeni načrt določi obseg izvoza, varen prenos, izbris aktivnih kopij in ravnanje z varnostnimi kopijami; ta stran ne uvaja nepotrjenih rokov 30/30/90 dni. Obvezne pravice do menjave ponudnika, prenosljivosti in dostopa ostanejo v veljavi in niso odložene do naslednjega letnega podaljšanja.", "Contact info@calendra.si to export or switch data. On termination, Calendra returns or deletes personal data and copies at the controller's choice, except where retention is legally required. The exit plan identifies export scope, secure transfer, active-copy deletion and backup handling; this page does not introduce unapproved 30/30/90-day retention promises. Mandatory switching, portability and access rights remain available and are not postponed until the next annual renewal."), p("Za dogovor se uporablja slovensko pravo ob upoštevanju prisilnih pravil. Ta različica ne določa nove številčne omejitve odgovornosti in ne izključuje odgovornosti, ki je ni mogoče izključiti. Bistvene spremembe pogodbe se obravnavajo z ustreznim predhodnim obvestilom oziroma soglasjem, ne samo s tiho zamenjavo spletne strani.", "Slovenian law applies subject to mandatory rules. This version introduces no new numerical liability cap and excludes no liability that cannot lawfully be excluded. Material contractual changes require appropriate advance notice or agreement, not merely a silent webpage replacement.")]),
      section("11. Ločeno: Connect in rezervacije posameznikov", "11. Separate: Connect and individual bookings", [p("Poslovna pravila o naročnini, 30-dnevni odpovedi in nevračilu ne veljajo samodejno za posameznika, ki prek Connect rezervira storitev. Storitev opravi ponudnik, naveden ob rezervaciji; pred potrditvijo mora navesti svojo identiteto, ceno ter pogoje plačila, odpovedi in vračil. Calendra ostaja odgovorna za lastne obveznosti platforme. Zakonske pravice potrošnikov niso izključene.", "The B2B subscription, 30-day non-renewal and no-change-of-mind-refund rules do not automatically apply to an individual booking through Connect. The provider identified in the booking supplies the service and must disclose its identity, price and payment, cancellation and refund terms before confirmation. Calendra remains responsible for its platform obligations. Statutory consumer rights are not excluded."), p("Connect lahko uporabljajo tudi mladoletni; trenutno ni splošne starostne omejitve izdelka. Sodelovanje upravičenega zastopnika je potrebno, kadar to zahteva pravna podlaga, pogodbena sposobnost ali konkretna storitev. Pri neposredno ponujeni spletni storitvi v Sloveniji, ki obdelavo opira na privolitev otroka, je pod 15 leti potrebna privolitev ali odobritev upravičene odrasle osebe. To ni splošna prepoved računov pod 15 leti in ni trditev, da je preverjanje starosti ali zastopanja že tehnično uvedeno.", "Minors may use Connect; there is currently no general product age restriction. An authorised representative must participate where required by the legal basis, contractual capacity or particular service. For a directly offered online service in Slovenia relying on a child's consent, an authorised adult must give or approve consent below age 15. This is not a blanket ban on accounts below 15, nor a claim that age or authority verification has already been implemented."), p("Uporabljajte samo račune in rezervacije, za katere imate pooblastilo. Izbris Connect računa ni nujno izbris strokovnih ali računovodskih evidenc pri ponudniku. Pravila posamezne rezervacije in obvezna pravna sredstva ostanejo ločena od poslovne pogodbe ponudnika s Calendro.", "Use only accounts and bookings you are authorised to manage. Deleting a Connect account does not necessarily delete professional or accounting records held by the provider. Individual booking rules and mandatory remedies remain separate from the provider's business subscription with Calendra.")], "connect"),
    ],
  },
  dpa: {
    title: p("Pogodba o obdelavi osebnih podatkov", "Data Processing Agreement"),
    intro: p("Pogoji za obdelavo osebnih podatkov v imenu poslovnega naročnika, vključno z opombami, datotekami, podporo in kršitvami varnosti.", "Terms for processing personal data on behalf of business customers, including notes, files, support and personal-data breaches."), review: true,
    sections: [
      section("1. Stranki, vloge in prednost", "1. Parties, roles and precedence", [identity, p("Upravljavec je poslovni naročnik, identificiran v podpisani pogodbi ali naročilu. Calendra je obdelovalec podatkov, ki jih obdeluje po njegovih navodilih. Za svoje naročnine, poslovne kontakte, lastno podporo in druge samostojno določene namene nastopa kot upravljavec skladno s politiko zasebnosti. Vloga se določa po dejanskem namenu obdelave, ne zgolj po imenu aplikacije. Ta DPA ima prednost pred neskladnimi splošnimi določili o obdelavi.", "The controller is the business customer identified in the signed agreement or order. Calendra is processor for data handled on its instructions. For its own subscriptions, business contacts, own support and other independently determined purposes, Calendra acts as controller under the Privacy Policy. Roles depend on the actual processing purpose, not merely the application name. This DPA prevails over inconsistent general processing terms.")]),
      section("2. Priloga A: obseg obdelave", "2. Annex A: processing scope", [p("Predmet in namen: zagotavljanje dogovorjenega koledarja, rezervacij, kontaktov, računov, plačilnih metapodatkov, obvestil, ugodnosti, integracij in shranjevanja opomb/datotek. Narava obdelave: zbiranje, organiziranje, shranjevanje, pridobivanje, prikaz pooblaščenim uporabnikom, prenos po navodilu, varnostno kopiranje in izbris. Obdelava traja med uporabo storitve ter med dogovorjenim zakonitim vračilom in izbrisom podatkov.", "Subject matter and purpose: the agreed calendar, bookings, contacts, invoicing, payment metadata, notifications, entitlements, integrations and note/file storage. Operations include collection, organisation, storage, retrieval, display to authorised users, instructed transfer, backup and deletion. Processing continues during service use and the agreed lawful return and deletion process."), p("Posamezniki: stranke in gosti naročnika, mladoletni uporabniki in upravičeni zastopniki, udeleženci, zaposleni, plačniki in kontaktne osebe. Podatki: identifikacijski in kontaktni podatki, termini in storitve, računovodski podatki, komunikacije, dovoljenja, datoteke in opombe, integracijski identifikatorji ter nujni tehnični dnevniki. Vsebina lahko vključuje zdravstvene ali svetovalne podatke, kadar jih naročnik zakonito vključi v dogovorjeni obseg; tudi podatek o rezervaciji lahko glede na okoliščine razkrije zdravstveno informacijo.", "Data subjects: the customer's clients and guests, minors and authorised representatives, participants, employees, payers and contact persons. Data includes identifiers and contacts, appointments and services, billing information, communications, permissions, files and notes, integration identifiers and necessary technical logs. Content may include health or counselling information where lawfully included in the agreed scope; appointment information itself may reveal health information depending on context."), NOTES_SCOPE]),
      section("3. Dokumentirana navodila in zaupnost", "3. Documented instructions and confidentiality", [p("Calendra obdeluje podatke samo po dokumentiranih navodilih upravljavca, tudi glede prenosov izven EGP, razen če obdelavo zahteva pravo EU ali države članice. V tem primeru upravljavca vnaprej obvesti, razen če zakon obvestilo prepoveduje. Če meni, da navodilo krši predpise o varstvu podatkov, upravljavca o tem nemudoma obvesti. Osebe, pooblaščene za obdelavo, morajo biti zavezane k zaupnosti.", "Calendra processes data only on documented controller instructions, including for transfers outside the EEA, unless EU or Member State law requires otherwise. It informs the controller beforehand unless prohibited by law. It informs the controller immediately if it considers an instruction to infringe data-protection law. Persons authorised to process data must be bound by confidentiality."), p("Naročnik določi potrebne podatke, pravne podlage, rok hrambe in pooblaščene uporabnike. Pri posebnih vrstah podatkov poleg ustrezne podlage iz 6. člena GDPR zagotovi veljaven pogoj iz 9. člena. Nobeno določilo ne preloži lastnih obveznosti Calendre na naročnika.", "The customer determines necessary data, lawful bases, retention and authorised users. For special-category information it establishes an applicable Article 9 condition as well as an Article 6 basis. No provision transfers Calendra's own obligations to the customer.")]),
      section("4. Priloga B: varnost in dostopi", "4. Annex B: security and access", [p("Calendra mora izvajati ukrepe, primerne tveganju, vključno z zaščito zaupnosti, celovitosti, razpoložljivosti in obnovljivosti ter ustreznim preverjanjem njihove učinkovitosti. Javni opis razpoložljivih kontrol je na strani Varnost. Natančne nastavitve gostovanja, šifriranja, varnostnih kopij, dostopa podpore in obnove se dokumentirajo v tehnični prilogi za dogovorjeno obdelavo. Uporaba S3 sama ne pomeni potrditve teh nastavitev ali varnostnega certifikata.", "Calendra must apply risk-appropriate measures protecting confidentiality, integrity, availability and recoverability, with appropriate evaluation of effectiveness. Available controls are summarised on the Security page. Exact hosting, encryption, backup, support-access and recovery settings are documented in the technical annex for the agreed processing. S3 use alone does not verify those settings or establish a security certification.")]),
      section("5. Priloga C: podobdelovalci in prenosi", "5. Annex C: subprocessors and transfers", [p("V okviru splošnega pisnega dovoljenja so podobdelovalci omejeni na tiste, ki so potrebni za dogovorjene funkcije. Calendra pred nameravano vključitvijo ali zamenjavo obvesti upravljavca ter mu omogoči smiselno možnost ugovora pred začetkom nove obdelave. Utemeljen ugovor stranki obravnavata in določita zakonito rešitev. Samo sprememba spletnega seznama brez ustreznega obvestila ni nadomestilo tega postopka.", "Under general written authorisation, subprocessors are limited to those needed for agreed functions. Calendra gives advance notice of intended additions or replacements and a meaningful opportunity to object before new processing begins. The parties address justified objections and establish a lawful resolution. Merely changing the website list without appropriate notice does not replace this process."), p("S podobdelovalcem se sklene zavezujoča pogodba z enakovrednimi obveznostmi varstva podatkov. Calendra ostaja odgovorna za izpolnjevanje teh obveznosti. Za prenose izven EGP se določi veljaven mehanizem, na primer ustrezen sklep o ustreznosti ali standardne pogodbene klavzule z zahtevano presojo in dodatnimi ukrepi. EU gostovanje ne pomeni, da vsaka integracija vse podatke obdeluje samo v EU.", "A binding subprocessor contract imposes equivalent data-protection obligations. Calendra remains responsible for their performance. Transfers outside the EEA require a valid mechanism, such as an applicable adequacy decision or standard contractual clauses with the required assessment and supplementary measures. EU hosting does not mean every integration processes all data exclusively in the EU.")]),
      section("6. Pomoč upravljavcu", "6. Assistance to the controller", [p("Ob upoštevanju narave obdelave Calendra z ustreznimi ukrepi pomaga pri zahtevah posameznikov. Neposredno prejeto zahtevo za podatke naročnika brez nepotrebnega odlašanja posreduje upravljavcu in je ne obravnava v nasprotju z njegovimi zakonitimi navodili. Ob upoštevanju informacij, ki so ji na voljo, pomaga pri obveznostih iz 32.–36. člena GDPR: varnosti, kršitvah, ocenah učinka in predhodnem posvetovanju. Organizacijska pravila ne smejo onemogočiti zakonsko zahtevane pomoči.", "Taking the nature of processing into account, Calendra assists with data-subject requests through appropriate measures. A request received directly concerning customer data is forwarded to the controller without undue delay and is not handled contrary to lawful instructions. Taking available information into account, it assists with Articles 32–36 GDPR: security, breach duties, impact assessments and prior consultation. Administrative arrangements must not obstruct legally required assistance.")]),
      section("7. Kršitve osebnih podatkov", "7. Personal-data breaches", [p("Calendra o kršitvi, ki zadeva podatke naročnika, obvesti upravljavca brez nepotrebnega odlašanja po seznanitvi s kršitvijo. Ne čaka na zaključek preiskave ali na popolne informacije. Obvestilo vsebuje tedaj znano naravo dogodka, prizadete kategorije in približne količine, kontakt, verjetne posledice ter sprejete oziroma predlagane ukrepe. Dopolnitve sledijo postopoma brez nepotrebnega odlašanja.", "Calendra notifies the controller of a breach affecting customer data without undue delay after becoming aware. It does not wait for a completed investigation or complete information. The notice includes the known nature of the event, affected categories and approximate numbers, a contact point, likely consequences and measures taken or proposed. Further information follows in phases without undue delay."), p("Upravljavec presodi svoje obveznosti do nadzornega organa in posameznikov; Calendra mu pomaga in izpolni tudi svoje lastne obveznosti. Morebitni 72-urni rok upravljavca ni dovoljenje za 72-urno čakanje obdelovalca. Dnevni urnik podpore teh obveznosti ne ustavi.", "The controller assesses its duties to supervisory authorities and individuals; Calendra assists and fulfils its own duties. A controller's possible 72-hour deadline does not permit a processor to wait 72 hours. The daytime support schedule does not pause these obligations.")], "krsitve"),
      section("8. Informacije, revizije in pregledi", "8. Information, audits and inspections", [p("Calendra upravljavcu zagotovi informacije, potrebne za dokazovanje izpolnjevanja obveznosti po 28. členu GDPR, ter omogoča revizije, vključno s pregledi, ki jih izvede upravljavec ali njegov pooblaščeni revizor, in pri njih sodeluje. Razumen dogovor o obsegu, zaupnosti in terminu varuje druge najemnike ter ne izniči pravice do revizije ali nujnega pregleda. Zahteve nadzornega organa ostanejo neomejene.", "Calendra makes available the information needed to demonstrate Article 28 compliance and allows and contributes to audits, including inspections by the controller or its mandated auditor. Reasonable scope, confidentiality and scheduling arrangements protect other tenants without defeating audit rights or urgent inspections. Supervisory-authority powers remain unaffected.")]),
      section("9. Priloga D: vračilo in izbris", "9. Annex D: return and deletion", [p("Po koncu storitve Calendra po izbiri upravljavca vrne ali izbriše osebne podatke ter izbriše obstoječe kopije, razen če pravo EU ali države članice zahteva hrambo. Potrdi se obseg izvoza, izvedba izbrisa in obravnava varnostnih kopij. Zakonska izjema se dokumentira in omeji na potrebne podatke; sklicevanje na tehnične možnosti ni splošna izjema od obveznosti izbrisa.", "After the service ends, Calendra returns or deletes personal data at the controller's choice and deletes existing copies unless EU or Member State law requires retention. Export scope, deletion completion and backup handling are confirmed. Legal exceptions are documented and limited to necessary data; technical convenience is not a blanket exemption from deletion duties."), p("Ta DPA ne določa nepreverjenega univerzalnega roka hrambe za opombe na S3 ali varnostne kopije. Obnovitev kopije ne sme trajno izničiti veljavnih navodil za izbris. Potrjena politika največ 14 dni za shranjena vprašanja AI-podpore je ločena od hrambe naročnikovih opomb, računov in dokumentov.", "This DPA does not assert an unverified universal retention period for S3 notes or backups. Restoring a backup must not permanently defeat valid deletion instructions. The approved maximum 14-day saved AI-support-question policy is separate from retention of the customer's notes, invoices and documents.")]),
      section("10. Spremembe, namen in lastna uporaba", "10. Changes, purpose and own use", [p("DPA ne dovoljuje prodaje podatkov naročnika, učenja splošnih modelov na njegovih evidencah ali deljenja občutljivih zapisov med nepovezanimi najemniki. Bistvene spremembe obdelave zahtevajo ustrezno obvestilo in po potrebi nov dogovor. Spletna objava sama ne nadomesti veljavnega sprejema DPA in konkretiziranih prilog.", "The DPA does not authorise sale of customer data, general-model training on customer records or sharing sensitive records between unrelated tenants. Material processing changes require appropriate notice and, where necessary, a new agreement. Website publication alone does not replace valid acceptance of the DPA and completed annexes.")]),
    ],
  },
  privacy: {
    title: p("Politika zasebnosti Calendra", "Calendra Privacy Policy"),
    intro: p("Osebni podatki na spletni strani, v aplikaciji, Connect, obrazcih za naročanje, opombah in podpori.", "Personal information on the website, application, Connect, hosted booking forms, notes and support."),
    sections: [
      section("1. Upravljavec in kontakt", "1. Controller and contact", [identity, p("Za zasebnost in zahteve posameznikov: info@calendra.si. Za obdelave, pri katerih Calendra sama določa namene, je upravljavec zgoraj navedeni ponudnik. Za evidence ponudnika storitve, ki uporablja Calendro, je praviloma upravljavec ta ponudnik, Calendra pa obdelovalec po DPA. Pri podpori, ki vključuje vpogled v naročnikove evidence, ta del obdelave ostane pod njegovimi navodili.", "For privacy and individual requests: info@calendra.si. Calendra's operator is controller where it determines the purposes. For records of a service provider using Calendra, that provider is generally controller and Calendra its processor under the DPA. Where support involves access to customer records, that processing remains subject to the customer's instructions.")]),
      section("2. Podatki in njihovi viri", "2. Information and sources", [p("Podatke prejmemo od vas, poslovnega naročnika ali pooblaščenega sodelavca, ob uporabi aplikacije ter iz povezave, ki jo omogočite. Sem sodijo ime, kontakt, organizacija, vloga in nastavitve, prijavni podatki, termini in storitve, plačilni in računovodski podatki, sporočila, opombe/datoteke, integracijski podatki ter tehnični in dostavni dnevniki. V podpori obdelujemo tudi vaša vprašanja in informacije, ki jih vnesete.", "Information comes from you, a business customer or authorised colleague, application use and integrations you enable. It includes names, contact details, organisation, roles and preferences, login information, appointments and services, payment and billing information, messages, notes/files, integration data and technical or delivery logs. Support also processes your questions and the information you submit."), NOTES_SCOPE]),
      section("3. Nameni in pravne podlage", "3. Purposes and lawful bases", [p("Pogodba oziroma koraki pred sklenitvijo (6(1)(b) GDPR): zahtevana storitev ali račun, kadar je posameznik sam pogodbena stranka. Zakoniti interes (6(1)(f)): običajna komunikacija s predstavniki poslovnih strank, pomoč pri uporabi, nujna varnost, preprečevanje zlorab in uveljavljanje pravnih zahtevkov, ob presoji sorazmernosti in pravici do ugovora. Pravna obveznost (6(1)(c)): obvezno računovodstvo, davki in druge zakonske zahteve.", "Contract or pre-contractual steps (Article 6(1)(b) GDPR): a requested service or account where the individual is a contracting party. Legitimate interests (Article 6(1)(f)): ordinary communications with business representatives, product assistance, necessary security, abuse prevention and legal claims, subject to proportionality and the right to object. Legal obligation (Article 6(1)(c)): mandatory accounting, tax and other statutory duties."), p("Privolitev (6(1)(a)): izbirne obdelave, za katere je potrebna, zlasti dovoljena analitična hramba in trženje, kjer pravila to zahtevajo. Privolitev lahko prekličete brez vpliva na predhodno zakonito obdelavo. Podatke naročnikovih strank obdelujemo po njegovih navodilih; namen in pravno podlago sporoči ta upravljavec. Podatki o zdravju lahko zahtevajo tudi pogoj iz 9. člena GDPR; oznaka »termin« jih ne izvzame samodejno.", "Consent (Article 6(1)(a)): optional processing requiring it, particularly permitted analytics storage and marketing where required. You may withdraw consent without affecting prior lawful processing. We process tenant-client information on the tenant's instructions; that controller explains its purposes and legal bases. Health information may also require an Article 9 condition; labelling information an appointment does not automatically exempt it."), p("Podatki, potrebni za zahtevani račun, rezervacijo ali obračun, so potrebni za izvedbo zadevne funkcije; brez njih je morda ni mogoče zagotoviti. Izbirni vnosi niso pogoj za nepovezane osnovne storitve. Če podatke o vas prejmemo od ponudnika storitve, mora biti razviden njihov vir in upravljavec. Za informacije o konkretnem viru nas kontaktirajte.", "Information necessary for a requested account, booking or billing is needed for that function; without it the function may not be possible. Optional inputs are not a condition for unrelated core services. When a service provider supplies information about you, the source and controller must be transparent. Contact us about a specific source.")]),
      section("4. Besedilna AI-podpora in hramba vprašanj", "4. Text AI support and saved questions", [p("Besedilni pomočnik je v uporabi; vprašanja uporabnikov se shranjujejo za obravnavo podpore in pregled vsebin pomoči. Po dokumentiranem toku lahko zahtevek ponudniku OpenAI vključuje oddano vprašanje, omejen pogovorni kontekst in navodila za uporabo produkta. Glasovni sistem ni v uporabi. V podporo ne vnašajte gesel, ključev, diagnoz ali nepotrebnih podatkov svojih strank; za pomoč lahko uporabite tudi e-pošto.", "The text assistant is live; user questions are saved for support handling and review of help content. The documented request to OpenAI may include the submitted question, limited conversation context and product guidance. The voice system is not live. Do not submit passwords, keys, diagnoses or unnecessary client records; email support remains available."), SAVED_QUESTION_RETENTION, p("Ta rok ne velja za opombe strank na S3, vse podporne dopise, tehnične metapodatke, varnostne kopije ali kopije pri zunanjem ponudniku. Te kategorije zahtevajo ločeno določen namen in hrambo. Redakcija osebnih podatkov ne zagotavlja popolne anonimnosti. Shranjevanje vprašanja ni dovoljenje za nepovezano učenje na evidencah strank ali za klinično AI-analizo.", "This limit does not apply to client notes on S3, all support correspondence, technical metadata, backups or copies held by an external provider. Those categories require separately defined purposes and retention. Redaction does not guarantee anonymity. Saving a question does not authorise unrelated training on client records or clinical AI analysis.")], "ai-podpora"),
      section("5. Hramba drugih podatkov", "5. Retention of other information", [p("Račune in davčne evidence hranimo v obsegu in času, ki ga zahteva zakon. Poslovne račune in pogodbeno komunikacijo hranimo med razmerjem ter toliko časa po njem, kolikor je utemeljeno zaradi zakonskih obveznosti ali zahtevkov. Naročnik določi potrebno hrambo svojih evidenc in zakonita navodila za izbris. Tehnični dnevniki se omejijo na obdobje, potrebno za varnost in diagnostiko. Podatki se ne hranijo za nedoločen čas samo zato, ker obstaja varnostna kopija.", "Invoices and tax records are retained to the extent and for the time required by law. Business accounts and contractual correspondence are retained during the relationship and afterwards only as justified by statutory duties or claims. Customers determine necessary retention of their records and lawful deletion instructions. Technical logs are limited to what security and diagnosis require. Backup existence alone does not justify indefinite retention."), p("Natančni roki za posamezne zapise, varnostne kopije in zunanjo obdelavo se preverjajo glede na dejanske nastavitve. Zahtevate lahko informacije o svoji kategoriji podatkov ter izvoz ali izbris, kadar je ta utemeljen. Ločeno identificiramo morebitno obvezno hrambo. Ta stran ne zatrjuje nepreverjenega 90-dnevnega izbrisa vseh kopij.", "Exact periods for particular records, backups and external processing are being checked against actual settings. You may request information about your data category and export or deletion where applicable. Any legally required retention is identified separately. This page does not assert unverified deletion of every copy within 90 days.")]),
      section("6. Prejemniki in prenosi", "6. Recipients and transfers", [p("Podatke po potrebi obdelujejo pooblaščene osebe, pogodbeni infrastrukturni in komunikacijski ponudniki, plačilne storitve ter omogočene integracije. Javni pregled je na strani Podobdelovalci. Posamezen zunanji ponudnik lahko za določene namene nastopa samostojno; njegova vloga je odvisna od storitve in pogodbe. Podatke pristojnim organom razkrijemo, kadar obstaja veljavna zahteva oziroma pravna podlaga.", "Information may be handled by authorised personnel, contracted infrastructure and communication providers, payment services and enabled integrations as needed. See the Subprocessors overview. A provider may act independently for certain purposes; its role depends on the service and agreement. Information is disclosed to authorities where a valid requirement or legal basis applies."), p("Gostovanje v EU ni zagotovilo, da vsaka integracija ali podpora deluje izključno v EU. Kadar je potreben prenos izven EGP, mora biti urejen z veljavnim mehanizmom in potrebnimi dodatnimi ukrepi. Za podatke o relevantnem prejemniku, državi in zaščiti oziroma kopiji ustreznih jamstev pišite na info@calendra.si; zaupne informacije se lahko ustrezno zaščitijo.", "EU hosting is not a guarantee that every integration or support operation is exclusively in the EU. Where a transfer outside the EEA is required, it must use a valid mechanism and necessary supplementary measures. Contact info@calendra.si for relevant recipients, locations and safeguards or a copy of applicable protections, with appropriate protection of confidential information.")]),
      section("7. Google povezave in Limited Use", "7. Google integrations and Limited Use", [p("The use and transfer of raw or derived user data received from Google Workspace APIs will adhere to the Google API Services User Data Policy, including the Limited Use requirements.", "The use and transfer of raw or derived user data received from Google Workspace APIs will adhere to the Google API Services User Data Policy, including the Limited Use requirements."), p("Google podatke uporabimo v obsegu omogočene funkcije, ne za prodajo, oglaševalsko profiliranje ali nepovezano uporabo. Odklop povezave ustavi nadaljnji dostop prek nje, ni pa samodejno izbris vsakega že zakonito ustvarjenega termina ali računa.", "Google data is used within the enabled feature, not for sale, advertising profiling or unrelated use. Disconnecting an integration stops further access through it but does not automatically delete every appointment or invoice already lawfully created.")]),
      section("8. Piškotki in mladoletni", "8. Cookies and minors", [p("Spletna stran uporablja samogostovano analitiko Umami in Google Analytics 4 z naprednim načinom soglasja. Analitično shranjevanje za Google je pred soglasjem zavrnjeno, vendar lahko Google prejme omejene meritve brez piškotkov. Ta posodobitev ne preklopi sistema na popolno blokiranje Google taga pred soglasjem. Podrobnosti in možnost spremembe izbire so v politiki in nastavitvah piškotkov.", "The website uses self-hosted Umami and Google Analytics 4 with Advanced Consent Mode. Google analytics storage is denied before consent, but Google may receive limited cookieless measurements. This update does not switch to blocking the Google tag completely before consent. Details and choice controls are in the Cookie Policy and settings."), p("Connect lahko uporabljajo mladoletni. Kadar neposredno ponujena spletna storitev v Sloveniji temelji na privolitvi otroka, je pod 15 leti potrebna odobritev upravičene odrasle osebe. Druga pravna podlaga ne odpravi obveznosti glede koristi otroka, obveščanja in pogodbene sposobnosti. Pooblastilo za rezervacijo ne pomeni samodejnega dostopa do vseh zaupnih zapisov ponudnika. Pravilna preveritev starosti in pooblastil ostaja ločena izvedbena obveznost.", "Minors may use Connect. Where a directly offered online service in Slovenia relies on a child's consent, an authorised adult's approval is required below age 15. Another legal basis does not remove duties concerning the child's interests, information and contractual capacity. Authority to book does not automatically grant access to every confidential provider record. Appropriate age and authority verification remains a separate implementation duty.")]),
      section("9. Pravice, ugovor in pritožba", "9. Rights, objection and complaints", [p("Ob zakonskih pogojih lahko zahtevate dostop, popravek, izbris, omejitev, prenosljivost ter ugovarjate obdelavi na podlagi zakonitega interesa; neposrednemu trženju lahko ugovarjate kadarkoli. Privolitev lahko prekličete. Pišite na info@calendra.si. Za evidence vašega ponudnika je praviloma prvi naslov ta ponudnik; pri usmeritvi in obravnavi pomagamo. Zahteve obravnavamo brez nepotrebnega odlašanja in praviloma v enem mesecu; o upravičenem podaljšanju za največ dva dodatna meseca in razlogih obvestimo v prvem mesecu.", "Subject to the legal conditions, you may request access, rectification, erasure, restriction and portability and object to legitimate-interest processing; you may object to direct marketing at any time. You may withdraw consent. Contact info@calendra.si. Your service provider is generally the first contact for its records; we assist with routing and handling. Requests are handled without undue delay and normally within one month; a justified extension of up to two further months and its reasons are communicated within the first month."), p("Pritožbo lahko vložite pri Informacijskem pooblaščencu Republike Slovenije oziroma drugem pristojnem nadzornem organu. Predhodni stik s Calendro ni pogoj za pritožbo. Ta politika ne razglaša avtomatiziranega sprejemanja pravno pomembnih odločitev; če bi tak proces uvedli, je potrebno posebno obvestilo in presoja njegovih varovalk.", "You may complain to Slovenia's Information Commissioner or another competent supervisory authority. Contacting Calendra first is not a prerequisite. This policy does not establish automated decision-making with legal or similarly significant effects; introducing such a process would require specific information and assessment of safeguards.")]),
    ],
  },
  security: {
    title: p("Varnost pri Calendri", "Security at Calendra"),
    intro: p("Varnost računov, obseg shranjevanja, prijava težav in ravnanje ob kršitvah osebnih podatkov.", "Account protection, storage scope, reporting security issues and handling personal-data breaches."),
    sections: [
      section("1. Prijava in seje", "1. Sign-in and sessions", [p("Gesla poslovnih uporabnikov se shranjujejo kot enosmerne zgoščene vrednosti z algoritmom bcrypt. Na voljo je izbirna dvostopenjska prijava s kodami iz aplikacije za preverjanje pristnosti. Uporabniki lahko pregledajo aktivne seje in odjavijo druge seje. Sprememba ali ponastavitev gesla prekliče obstoječe seje poslovnega računa; za izbrane občutljive spremembe je potrebna ponovna potrditev gesla.", "Business-user passwords are stored as one-way bcrypt hashes. Optional two-factor sign-in with authenticator-app codes is available. Users can review active sessions and sign out other sessions. Changing or resetting a password revokes existing business-account sessions; selected sensitive changes require password confirmation.")]),
      section("2. Pravice in odgovornosti", "2. Permissions and responsibilities", [p("Strežnik preverja dostop poslovnega uporabnika do izbrane organizacije in pripadnost poslovnega prostora tej organizaciji. Dostop do funkcij je odvisen od vloge in pravic. Skrbnik naj dodeli najmanjši potreben obseg dostopa in ga odstrani ob odhodu sodelavca. To ni zagotovilo o ločitvi vsakega posameznega polja ali kliničnega zapisa; zahteve konkretne prakse je treba preveriti pred uporabo.", "The server checks a business user's access to the selected organisation and that the business location belongs to it. Feature access depends on roles and permissions. Administrators should assign the minimum necessary access and remove it when staff leave. This is not a guarantee of isolation for every individual field or clinical record; practice-specific requirements must be checked before use.")]),
      section("3. Opombe, datoteke in varnostna priloga", "3. Notes, files and security annex", [NOTES_SCOPE, p("Dokumentacija za naročnika mora opisati dejansko regijo, način dostopa do datotek, šifriranje, kopije in obnovo za dogovorjeno obdelavo. Ta stran ne zatrjuje neodvisnega varnostnega certifikata, opravljenega penetracijskega testa, posebne sheme šifriranja ali preverjenega časa obnove, za katere ni dokumentiranih dokazov. Povzetek ni nadomestilo tehnične priloge k DPA.", "Customer documentation must describe actual regions, file access, encryption, backups and recovery for the agreed processing. This page does not assert an independent security certification, completed penetration test, particular encryption scheme or verified recovery time without documented evidence. This summary does not replace the DPA technical annex.")]),
      section("4. Prijava varnostne težave", "4. Reporting a security issue", [p("Pišite na info@calendra.si in v zadevi označite »Varnostni incident«. Navedite čas, prizadeto funkcijo, opaženi vpliv in varne korake za ponovitev. Ne pošiljajte gesel, ključev, zasebnih povezav ali podatkov drugih uporabnikov. Brez dovoljenja ne izvajajte obremenjevanja, dostopanja do tujih računov ali drugih posegov.", "Email info@calendra.si with the subject Security incident. Include the time, affected function, observed impact and safe reproduction steps. Do not send passwords, keys, private access links or other users' records. Do not conduct load tests, access others' accounts or perform intrusive testing without permission.")]),
      section("5. Ravnanje ob kršitvi osebnih podatkov", "5. Handling a personal-data breach", [p("Ob zaznavi zabeležimo dogodek, ocenimo obseg in tveganje, omejimo nadaljnjo škodo ter zavarujemo potrebne dokaze. O kršitvi podatkov naročnika obvestimo upravljavca brez nepotrebnega odlašanja po seznanitvi. Prvo obvestilo se ne odloži do zaključka preiskave; manjkajoče informacije dopolnimo postopoma.", "On detection, we record the incident, assess scope and risk, contain further harm and preserve necessary evidence. We notify the controller of a breach of its data without undue delay after awareness. The first notice is not postponed until the investigation finishes; missing information is supplied in phases."), p("Obvestilo vsebuje znano naravo kršitve, prizadete kategorije in približne količine, kontakt, verjetne posledice in ukrepe. Kadar je Calendra upravljavec, pristojni organ obvesti brez nepotrebnega odlašanja in, kadar je to izvedljivo, najpozneje v 72 urah po seznanitvi, razen če je malo verjetno tveganje za pravice in svoboščine. Pri verjetnem visokem tveganju brez nepotrebnega odlašanja obvesti tudi prizadete posameznike, ob upoštevanju zakonskih izjem. Odločitve in razloge dokumentira.", "The notice includes the known nature of the breach, affected categories and approximate numbers, a contact point, likely consequences and measures. When Calendra is controller, it notifies the competent authority without undue delay and, where feasible, within 72 hours of awareness unless risk to rights and freedoms is unlikely. Likely high risk also requires communication to affected individuals without undue delay, subject to statutory exceptions. Decisions and reasons are documented."), p("Roki za kršitve niso običajni odzivni roki podpore. Ne ustavijo se ponoči, ob koncu tedna ali prazniku. Rok 72 ur za upravljavca ni splošni rok, do katerega sme obdelovalec odlašati z obvestilom naročniku.", "Breach deadlines are not ordinary support-response deadlines. They do not pause overnight, at weekends or on holidays. The controller's 72-hour deadline is not a general period during which a processor may delay notifying a customer.")], "incidenti"),
      section("6. Podpora in dodatne informacije", "6. Support and further information", [SUPPORT_HOURS, SUPPORT_RESPONSE]),
    ],
  },
  aiTransparency: {
    title: p("AI transparentnost za Calendra", "AI transparency for Calendra"),
    intro: p("Besedilna AI-podpora je v uporabi in shranjuje uporabniška vprašanja. Glasovni sistem ni v uporabi.", "Text AI support is live and saves user questions. The voice system is not live."),
    sections: [
      section("1. Kaj pomočnik počne", "1. What the assistant does", [p("Pomočnik uporablja OpenAI za odgovore o uporabi Calendre. AI-odgovor ni odgovor človeka in lahko vsebuje napake. Preglejte navodila pred izvedbo pomembne spremembe; za človeško pomoč pišite na info@calendra.si. Pomočnik ni namenjen diagnozam, psihološki obravnavi, pravnemu svetovanju ali nujnim primerom.", "The assistant uses OpenAI to answer questions about using Calendra. An AI answer is not a human response and can be wrong. Review guidance before making important changes; contact info@calendra.si for human assistance. It is not intended for diagnosis, counselling, legal advice or emergencies.")]),
      section("2. Posredovani podatki in obseg", "2. Data sent and scope", [p("Zahtevek lahko vsebuje uporabnikovo vprašanje, omejen predhodni pogovorni kontekst in navodila oziroma odobrene vsebine pomoči. Ne vnašajte podatkov, ki za podporo niso potrebni. Shranjevanje opomb ali dokumentov na S3 ne daje dovoljenja, da se ti uporabijo za podporni AI ali učenje na evidencah strank. Glasovni ukazi, snemanje in klinična analiza niso vključeni v opis trenutno delujoče podporne funkcije.", "A request may contain the user's question, limited preceding conversation context and instructions or approved help material. Do not enter information unnecessary for support. Storing notes or documents on S3 does not authorise use of them for support AI or training on client records. Voice commands, recording and clinical analysis are not included in this description of the live support feature.")]),
      section("3. Shranjena vprašanja", "3. Saved questions", [SAVED_QUESTION_RETENTION, p("Shranjevanje vprašanj je vključeno. Uporablja se za obravnavo podpore in pregled vsebine pomoči, ne pomeni pa samodejne objave vprašanj ali dovoljenja za nepovezano ponovno uporabo. Odstranjevanje neposrednih identifikatorjev ne zagotavlja anonimnosti. Dostop, izvoze in roke za ločene metapodatke, ročne izpise ter kopije je treba obravnavati posebej; 14-dnevni rok ni splošno zagotovilo za vse sisteme.", "Question saving is enabled for support handling and review of help content; it does not mean automatic publication or authorisation for unrelated reuse. Removing direct identifiers does not guarantee anonymity. Access, exports and retention of separate metadata, manual exports and copies need separate handling; the 14-day policy is not a blanket guarantee covering every system.")]),
      section("4. Obdelava pri ponudniku", "4. Provider processing", [p("OpenAI je zunanji ponudnik. Njegova obdelava in hramba sta ločeni od aktivne zbirke shranjenih vprašanj pri Calendri. Nastavitev zahtevka brez shranjevanja sama po sebi ne dokazuje ničelne hrambe pri ponudniku. Ne zatrjujemo posebej odobrene ničelne hrambe ali obdelave izključno v EU brez preveritve dejanskega računa, končnih točk in pogodbe.", "OpenAI is an external provider. Its processing and retention are separate from Calendra's active saved-question store. A request setting disabling storage does not by itself prove zero provider retention. We do not claim specially approved zero retention or exclusively EU processing without verification of the actual account, endpoints and agreement.")]),
      section("5. Izbira in nadaljnje spremembe", "5. Choice and changes", [p("Namesto AI lahko uporabite človeško podporo po e-pošti. Za informacije o shranjenem vprašanju, ugovor ali izbris pišite na info@calendra.si. Ob uvedbi nove vrste AI, zlasti glasovnih ali kliničnih funkcij, morajo biti pred uporabo ustrezno opisani namen, podatki, ponudniki, hramba in nadzor. Ta stran ne nadomešča obvestila ob sami interakciji v aplikaciji.", "You can use human email support instead of AI. Contact info@calendra.si about a saved question, objection or deletion. A new type of AI, particularly voice or clinical functionality, must have appropriate purpose, data, provider, retention and control information before use. This page does not replace disclosure at the interaction in the application.")]),
    ],
  },
  dataRights: {
    title: p("Pravice posameznikov", "Data subject rights"), intro: p("Kako zahtevati informacije, dostop, popravek, izbris ali druga dejanja glede osebnih podatkov.", "How to request information, access, correction, deletion or other action concerning personal data."),
    sections: [
      section("1. Kako vložiti zahtevo", "1. Making a request", [p("Pišite na info@calendra.si. Navedite, ali gre za vaš Connect račun, poslovni račun, shranjeno podporno vprašanje ali podatke pri določenem ponudniku. Ne pošiljajte gesel ali nepotrebnih osebnih dokumentov. Identiteto preverimo sorazmerno; dodatne podatke zahtevamo le, kadar je to potrebno.", "Email info@calendra.si and identify whether the request concerns Connect, a business account, a saved support question or records at a specific provider. Do not send passwords or unnecessary identity documents. Identity checks are proportionate; additional information is requested only where necessary.")]),
      section("2. Upravljavec in roki", "2. Controller and deadlines", [p("Za podatke ponudnika storitve je ta praviloma upravljavec; pomagamo vam najti pravi naslov in mu posredujemo zahtevo. Za lastne obdelave Calendra zahtevo obravnava sama. Odgovor sledi brez nepotrebnega odlašanja, praviloma v enem mesecu. Ob kompleksnosti ali večjem številu zahtev je možno utemeljeno podaljšanje za največ dva dodatna meseca; o njem in razlogih vas obvestimo v prvem mesecu. Urnik običajne podpore ne spremeni zakonskih rokov.", "Your service provider is generally controller of its records; we help identify it and forward the request. Calendra handles its own controller processing directly. A response is provided without undue delay, normally within one month. Complexity or request volume may justify an extension of up to two further months, with reasons communicated within the first month. Ordinary support hours do not alter statutory deadlines.")]),
      section("3. Pravice in izjeme", "3. Rights and exceptions", [p("Ob izpolnjenih pogojih imate pravice do dostopa, popravka, izbrisa, omejitve, prenosljivosti in ugovora. Privolitev lahko prekličete; neposrednemu trženju lahko ugovarjate kadarkoli. Izbris ni absoluten, na primer kadar zakon zahteva hrambo računa; omejitev pojasnimo za konkretne podatke. Zahteve so praviloma brezplačne; morebitne zakonske izjeme se obrazložijo. Pritožbo lahko vložite pri Informacijskem pooblaščencu Republike Slovenije ali drugem pristojnem organu.", "Where conditions are met, you have rights to access, rectification, erasure, restriction, portability and objection. You can withdraw consent and object to direct marketing at any time. Erasure is not absolute, for example where an invoice must be legally retained; any limitation is explained for the particular data. Requests are normally free; statutory exceptions must be justified. You may complain to Slovenia's Information Commissioner or another competent authority.")]),
    ],
  },
  accountDeletion: {
    title: p("Izbris računa Calendra Connect", "Calendra Connect account deletion"), intro: p("Zahteva za zaprtje računa in pojasnilo, katere evidence so ločene od vašega računa.", "Requesting account closure and understanding which records are separate from your account."),
    sections: [
      section("1. Zahteva za izbris", "1. Request deletion", [p("Z e-poštnega naslova svojega računa pišite na info@calendra.si z zadevo »Izbris računa Calendra Connect«. Če dostopa do tega naslova nimate, nas kontaktirajte za sorazmerno preveritev identitete. Gesla ali dostopni ključi niso potrebni. Izbris lahko zahtevate tudi neodvisno od razpoložljivosti posameznega gumba v aplikaciji.", "Email info@calendra.si from your account address with the subject Delete Calendra Connect account. If you cannot access that address, contact us for proportionate identity verification. Passwords and access keys are not required. You can request deletion independently of whether a particular in-app button is available.")]),
      section("2. Kaj izbris pomeni", "2. What deletion means", [p("Zaprtje Connect računa ni samodejna odpoved vseh dogovorjenih terminov ali izbris vseh evidenc ponudnika. Najemnik lahko določen račun ali strokovno evidenco zakonito hrani kot samostojni upravljavec. Pri zahtevi pojasnimo, katere podatke izbrišemo, katere posredujemo v obravnavo ponudniku in za katere obstaja zakonita izjema. Ne obljubljamo takojšnjega izbrisa vseh varnostnih kopij.", "Closing a Connect account does not automatically cancel every appointment or erase all provider records. A tenant may lawfully retain a particular invoice or professional record as controller. We explain which data is erased, which requests are forwarded to the provider and which legal exceptions apply. We do not promise immediate deletion of every backup."), p("Za poslovni naročniški račun veljajo ločena pravila nepodaljšanja in izvoza iz pogodbe. Uveljavljanje pravic posameznika ni isto kot odpoved B2B naročnine in ni odloženo samo zaradi 30-dnevnega odpovednega roka.", "Business subscription accounts have separate contractual non-renewal and export rules. Exercising individual privacy rights is not the same as cancelling a B2B subscription and is not postponed merely because of the 30-day non-renewal deadline.")]),
    ],
  },
  cookies: {
    title: p("Politika piškotkov", "Cookie Policy"), intro: p("Piškotki, lokalno shranjevanje in analitika na javni spletni strani Calendra.", "Cookies, local storage and analytics on the public Calendra website."),
    sections: [
      section("1. Trenutna nastavitev", "1. Current configuration", [p("Za osnovno merjenje obiska uporabljamo samogostovani Umami brez piškotkov, dodatno pa Google Analytics 4 z naprednim načinom soglasja. Google tag se naloži z analitičnim shranjevanjem privzeto zavrnjenim. Pred soglasjem ne nastavlja analitičnih piškotkov, lahko pa Googlu pošlje omejene meritve brez piškotkov. Oglaševalske vrste soglasja ostanejo onemogočene.", "Baseline traffic measurement uses self-hosted, cookieless Umami; Google Analytics 4 additionally uses Advanced Consent Mode. The Google tag loads with analytics storage denied by default. Before consent it does not set analytics cookies, but may send limited cookieless measurements to Google. Advertising consent types remain disabled."), p("Odsotnost piškotkov ni trditev, da ni nobene obdelave osebnih podatkov. Predlagani prehod na popolno blokiranje GA4 do privolitve še ni potrjen ali izveden s to posodobitvijo. Opis tukaj ne spreminja delovanja taga.", "Absence of cookies is not a claim that no personal-data processing occurs. The proposed change to block GA4 completely until opt-in has not been approved or implemented by this update. This description does not alter tag behaviour.")]),
      section("2. Namen in podatki", "2. Purpose and data", [p("Nujno shranjevanje podpira delovanje, varnost, jezik in vašo izbiro glede analitike. Analitika meri oglede, vir obiska, vrsto naprave in brskalnika ter dogodke, kot je klik na predstavitev. Analitično shranjevanje Google se omogoči po izbiri »Dovoli analitiko«. V analitiko ne pošiljamo vsebine obrazcev, imen, e-poštnih naslovov ali telefonskih številk.", "Necessary storage supports operation, security, language and your analytics choice. Analytics measures page views, referrers, device and browser type and events such as a demo click. Google analytics storage is enabled after selecting Allow analytics. Form contents, names, email addresses and phone numbers are not sent to analytics.")]),
      section("3. Vaša izbira", "3. Your choice", [p("Izbiro lahko spremenite prek povezave »Nastavitve piškotkov« v nogi. Piškotke in lokalno shranjevanje lahko upravljate tudi v brskalniku. Blokiranje nujnih tehnologij lahko vpliva na delovanje. Zahtevate lahko podatke o dejansko uporabljenih ključih in rokih; njihov inventar je treba uskladiti z nameščeno konfiguracijo, ne povzeti iz privzetih vrednosti ponudnika. Kontakt: info@calendra.si.", "Change your choice through Cookie settings in the footer. Cookies and local storage can also be managed in your browser. Blocking necessary technologies may affect functionality. You may request information about actual storage keys and lifetimes; the inventory must match the deployed configuration rather than assumed provider defaults. Contact: info@calendra.si.")]),
    ],
  },
  support: {
    title: p("Podpora za Calendro", "Calendra support"), intro: p("Pomoč pri uporabi, odzivni časi in prijava težav.", "Product assistance, response commitments and reporting problems."),
    sections: [
      section("1. Kontakt", "1. Contact", [p(`Pišite na ${LEGAL.supportEmail} ali pokličite ${LEGAL.supportPhone}. Za tehnično vprašanje navedite podjetje, prizadeto funkcijo, čas dogodka in varen opis korakov. Ne pošiljajte gesel, ključev ali zaupnih zapisov strank.`, `Email ${LEGAL.supportEmail} or call ${LEGAL.supportPhone}. For a technical enquiry, identify your business, affected function, time and safe reproduction steps. Do not send passwords, keys or confidential client records.`)]),
      section("2. Delovni čas in prvi odgovor", "2. Hours and first response", [SUPPORT_HOURS, SUPPORT_RESPONSE, p("Primer štetja: vprašanje ob 19:00 porabi eno uro do 20:00; štetje se nadaljuje naslednji dan ob 08:00, tudi če je vikend ali praznik. Varnostne incidente prijavite takoj; zakonske obveznosti ob kršitvi ne čakajo na običajno podporno okno.", "Example: a request at 19:00 accrues one hour by 20:00; counting resumes the following day at 08:00, including weekends or holidays. Report security incidents immediately; statutory breach duties do not wait for the ordinary support window.")]),
      section("3. AI in človeška pomoč", "3. AI and human help", [p("Besedilni pomočnik je na voljo za vprašanja o produktu, vendar njegovi odgovori ne štejejo kot človeški prvi vsebinski odgovor. Shranjevanje podpornih vprašanj je vključeno; podrobnosti so na strani AI transparentnost. Glasovni pomočnik ni v uporabi. Za nadaljnjo pomoč izberite e-poštni kontakt.", "The text assistant helps with product questions, but its answers do not count as a substantive first human response. Support-question saving is enabled; see AI Transparency for details. The voice assistant is not live. Use email for further human assistance.")]),
    ],
  },
};
